#include <iostream>
class Buffer {
public:
    int* data;
    size_t size;
    // Move constructor
    Buffer(Buffer&& rhs) noexcept : data(rhs.data), size(rhs.size) {
        rhs.data = nullptr; // Leave source in valid state
        rhs.size = 0;
        std::cout << "Move constructor called" << std::endl;
    }
    // Constructor
    Buffer(size_t s) : data(new int[s]), size(s) { }
    // Destructor
    ~Buffer() { delete[] data; }
};

int main() {
    Buffer buf1(10);
    Buffer buf2(std::move(buf1)); // Invokes move constructor
    std::cout << "buf1 data pointer: " << buf1.data << std::endl;
    std::cout << "buf2 data pointer: " << buf2.data << std::endl;
    return 0;
}
